namespace sitesplat\bblc_custom_css;
class bblivechat { protected $css = ''; protected $classes = ''; public function __construct() { global $cache, $db; $css_classes = $cache->get('_bblc_customcss'); if ($css_classes === false) { $sql = 'SELECT config_value FROM ' . CONFIG_TEXT_TABLE . " WHERE config_name = 'bblc_customcss'"; $result = $db->sql_query($sql); $css_classes = (string) $db->sql_fetchfield('config_value'); $db->sql_freeresult($result); if (!$css_classes) { $css_classes = json_encode(['', ''], 320); $db->sql_query('REPLACE INTO ' . CONFIG_TEXT_TABLE . " VALUES('bblc_customcss', '$css_classes')"); } $cache->put('_bblc_customcss', $css_classes); } list($this->classes, $this->css) = json_decode($css_classes, true); \sitesplat\add_filter('bblivechat_css', [$this, 'add_css'], 1); \sitesplat\add_filter('bblivechat_content_classes', [$this, 'add_classes'], 1); \sitesplat\add_filter('bblc_handle_acp_settings', [$this, 'customcss_handle'], 1); \sitesplat\add_filter('bblc_display_acp_settings', [$this, 'customcss_form'], 2); } public function add_css($css) { return $css . $this->css; } public function add_classes($classes) { return ($this->classes) ? $classes . " {$this->classes}" : $classes; } public function customcss_handle($error) { global $cache, $db, $language, $request; $css = htmlspecialchars_decode($request->variable('bblc_css', '', true)); $classes = $request->variable('bblc_classes', ''); $err = false; if (strlen($css) > 64000) { $error[] = sprintf($language->lang('SETTING_TOO_LONG'), $language->lang('BBLC_CCSS'), 64000); $err = true; } if (strlen($classes) > 255) { $error[] = sprintf($language->lang('SETTING_TOO_LONG'), $language->lang('BBLC_CCLASS'), 255); $err = true; } if (preg_match('`[^A-Za-z0-9-_ ]`', $classes)) { $language->add_lang('ucp'); $error[] = sprintf($language->lang('FIELD_INVALID_VALUE'), $language->lang('BBLC_CCLASS')); $err = true; } if (!$err) { $css_classes = $db->sql_escape(json_encode([$classes, $css], 320)); $db->sql_query('REPLACE INTO ' . CONFIG_TEXT_TABLE . " VALUES('bblc_customcss', '$css_classes')"); $cache->destroy('_bblc_customcss'); } return $error; } public function customcss_form($html) { global $language; $cllabel = $language->lang('BBLC_CCLASS') . $language->lang('COLON'); $clexplain = $language->lang('BBLC_CCLASS_EXPLAIN'); $classes = $this->classes; $csslabel = $language->lang('BBLC_CCSS') . $language->lang('COLON'); $cssexplain = $language->lang('BBLC_CCSS_EXPLAIN'); $css = $this->css; return $html . <<<EOT
<dl> <dt><label>$cllabel</label><span>$clexplain</span></dt> <dd><input type="text" name="bblc_classes" value="$classes" maxlength="255" /></dd> </dl> <br /> <dl> <dt style="width:auto;border-right:none"><label>$csslabel</label><span>$cssexplain</span></dt> <div style="clear:both;height:8px"></div> <textarea name="bblc_css" rows="8" cols="80" style="width:90%">$css</textarea> </dl> <hr />
EOT;
} }